#!/usr/bin/env python3
import os
import sys
import time
import re
import subprocess
from datetime import datetime

VERSION = "loop 0.6.1"
ABOUT = "UNIX's missing `loop` command"
AUTHOR = "Rich Jones <miserlou@gmail.com>"

LONG_FLAGS = {
    "error-duration": "error_duration",
    "help": "help",
    "only-last": "only_last",
    "stdin": "stdin",
    "summary": "summary",
    "until-changes": "until_changes",
    "until-fail": "until_fail",
    "until-same": "until_same",
    "until-success": "until_success",
    "version": "version",
}
SHORT_FLAGS = {
    "D": "error_duration",
    "h": "help",
    "l": "only_last",
    "i": "stdin",
    "C": "until_changes",
    "f": "until_fail",
    "S": "until_same",
    "s": "until_success",
    "V": "version",
}
LONG_OPTS = {
    "count-by": ("count_by", "count_by", "b"),
    "every": ("every", "every", "e"),
    "for": ("ffor", "ffor", None),
    "for-duration": ("for_duration", "for_duration", "d"),
    "num": ("num", "num", "n"),
    "offset": ("offset", "offset", "o"),
    "until-contains": ("until_contains", "until_contains", "c"),
    "until-error": ("until_error", "until_error", "r"),
    "until-match": ("until_match", "until_match", "m"),
    "until-time": ("until_time", "until_time", "t"),
}
SHORT_OPTS = {v[2]: (k, v[0], v[1]) for k, v in LONG_OPTS.items() if v[2]}

HELP_TEMPLATE = """loop 0.6.1
Rich Jones <miserlou@gmail.com>
UNIX's missing `loop` command

USAGE:
    {prog} [FLAGS] [OPTIONS] [input]...

FLAGS:
    -D, --error-duration    Exit with timeout error code on duration
    -h, --help              Prints help information
    -l, --only-last         Only print the output of the last execution of the command
    -i, --stdin             Read from standard input
        --summary           Provide a summary
    -C, --until-changes     Keep going until the output changes
    -f, --until-fail        Keep going until the command exit status is non-zero
    -S, --until-same        Keep going until the output changes
    -s, --until-success     Keep going until the command exit status is zero
    -V, --version           Prints version information

OPTIONS:
    -b, --count-by <count_by>                Amount to increment the counter by [default: 1]
    -e, --every <every>                      How often to iterate. ex., 5s, 1h1m1s1ms1us [default: 1us]
        --for <ffor>                         A comma-separated list of values, placed into 4ITEM. ex., red,green,blue
    -d, --for-duration <for_duration>        Keep going until the duration has elapsed (example 1m30s)
    -n, --num <num>                          Number of iterations to execute
    -o, --offset <offset>                    Amount to offset the initial counter by [default: 0]
    -c, --until-contains <until_contains>    Keep going until the output contains this string
    -r, --until-error <until_error>          Keep going until the command exit status is the value given
    -m, --until-match <until_match>          Keep going until the output matches this regular expression
    -t, --until-time <until_time>            Keep going until a future time, ex. "2018-04-20 04:20:00" (Times in UTC.)

ARGS:
    <input>...    The command to be looped
"""

def progname():
    return os.path.basename(sys.argv[0]) or "executable"

class CliError(Exception):
    def __init__(self, msg, usage=None):
        self.msg = msg
        self.usage = usage


def print_help():
    sys.stdout.write(HELP_TEMPLATE.format(prog=progname()))


def usage_for_general():
    return f"USAGE:\n    {progname()} [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n"


def usage_for_missing(opt_long):
    # clap v2 includes defaulted options in this common missing-value case
    return f"USAGE:\n    {progname()} --count-by <count_by> --every <every> --{opt_long} <{LONG_OPTS.get(opt_long, (opt_long,opt_long,None))[1]}> --offset <offset>\n\nFor more information try --help\n"


def fail_unknown(arg):
    raise CliError(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n" + usage_for_general())


def fail_missing(longname):
    valname = LONG_OPTS.get(longname, (longname, longname, None))[1]
    raise CliError(f"error: The argument '--{longname} <{valname}>' requires a value but none was supplied\n\n" + usage_for_missing(longname))


def decimal_places(s):
    # The observed counter formatting follows the number of digits after '.'
    # in --count-by, ignoring exponent notation.
    if s is None:
        return 0
    if "." not in s:
        return 0
    tail = s.split(".", 1)[1]
    # If an exponent is present, only count the literal fractional digits.
    tail = tail.split("e", 1)[0].split("E", 1)[0]
    return len(tail)


def parse_cli(argv):
    opts = {
        "error_duration": False, "help": False, "only_last": False,
        "stdin": False, "summary": False, "until_changes": False,
        "until_fail": False, "until_same": False, "until_success": False,
        "version": False,
        "count_by": "1", "every": "1us", "ffor": None,
        "for_duration": None, "num": None, "offset": "0",
        "until_contains": None, "until_error": None, "until_match": None,
        "until_time": None,
    }
    inputs = []
    i = 0
    parsing = True
    while i < len(argv):
        arg = argv[i]
        if parsing and arg == "--":
            inputs.extend(argv[i+1:])
            break
        if parsing and arg.startswith("--") and len(arg) > 2:
            nameval = arg[2:]
            if "=" in nameval:
                name, val = nameval.split("=", 1)
                has_val = True
            else:
                name, val = nameval, None
                has_val = False
            if name in LONG_FLAGS:
                if has_val:
                    # close enough to clap's treatment for bad flag values
                    fail_unknown(arg)
                opts[LONG_FLAGS[name]] = True
                i += 1
                continue
            if name in LONG_OPTS:
                key, _valname, _short = LONG_OPTS[name]
                if not has_val:
                    if i + 1 >= len(argv):
                        fail_missing(name)
                    # clap does not accept a detached negative number as an option value
                    if argv[i+1].startswith("-"):
                        fail_unknown(argv[i+1])
                    val = argv[i+1]
                    i += 1
                opts[key] = val
                i += 1
                continue
            fail_unknown(arg)
        elif parsing and arg.startswith("-") and arg != "-":
            rest = arg[1:]
            j = 0
            while j < len(rest):
                ch = rest[j]
                if ch in SHORT_FLAGS:
                    opts[SHORT_FLAGS[ch]] = True
                    j += 1
                    continue
                if ch in SHORT_OPTS:
                    longname, key, _valname = SHORT_OPTS[ch]
                    val = rest[j+1:]
                    if val.startswith("="):
                        val = val[1:]
                    if val == "":
                        if i + 1 >= len(argv):
                            fail_missing(longname)
                        if argv[i+1].startswith("-"):
                            fail_unknown(argv[i+1])
                        val = argv[i+1]
                        i += 1
                    opts[key] = val
                    j = len(rest)
                    break
                fail_unknown("-" + ch)
            i += 1
            continue
        else:
            inputs.append(arg)
            i += 1
    return opts, inputs


def parse_float_value(s, opt_long, valname):
    try:
        return float(s)
    except Exception:
        raise CliError(f"error: Invalid value for '--{opt_long} <{valname}>': invalid float literal\n")


def parse_duration(s, opt_long, valname):
    if s == "":
        raise CliError(f"error: Invalid value for '--{opt_long} <{valname}>': value was empty\n")
    units = {
        "ns": 1e-9,
        "us": 1e-6,
        "µs": 1e-6,
        "ms": 1e-3,
        "s": 1.0,
        "m": 60.0,
        "h": 3600.0,
        "d": 86400.0,
    }
    pos = 0
    total = 0.0
    n = len(s)
    while pos < n:
        if not s[pos].isdigit():
            if s[pos] == '.':
                msg = f"invalid character at {pos}"
            else:
                msg = f"expected number at {pos}"
            raise CliError(f"error: Invalid value for '--{opt_long} <{valname}>': {msg}\n")
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        num = int(s[start:pos])
        unit = None
        for u in ("ms", "us", "µs", "ns", "d", "h", "m", "s"):
            if s.startswith(u, pos):
                unit = u
                break
        if unit is None:
            # observed format for bare number at end: unknown unit at 1-1
            raise CliError(f"error: Invalid value for '--{opt_long} <{valname}>': unknown unit at {pos}-{pos}\n")
        pos += len(unit)
        total += num * units[unit]
    return total


def validate(opts):
    count_by = parse_float_value(opts["count_by"], "count-by", "count_by")
    offset = parse_float_value(opts["offset"], "offset", "offset")
    num = None
    if opts["num"] is not None:
        num = int(parse_float_value(opts["num"], "num", "num"))
    every = parse_duration(opts["every"], "every", "every")
    for_duration = None
    if opts["for_duration"] is not None:
        for_duration = parse_duration(opts["for_duration"], "for-duration", "for_duration")
    until_re = None
    if opts["until_match"] is not None:
        try:
            until_re = re.compile(opts["until_match"])
        except re.error as e:
            # Python's wording differs from Rust regex; keep the leading line exact.
            raise CliError(f"error: Invalid value for '--until-match <until_match>': {e}\n")
    until_dt = None
    if opts["until_time"] is not None:
        try:
            until_dt = datetime.strptime(opts["until_time"], "%Y-%m-%d %H:%M:%S")
        except Exception:
            raise CliError("error: Invalid value for '--until-time <until_time>': timestamp format is invalid\n")
    return {
        "count_by": count_by,
        "offset": offset,
        "num": num,
        "every": every,
        "for_duration": for_duration,
        "until_re": until_re,
        "until_dt": until_dt,
        "count_precision": decimal_places(opts["count_by"]),
    }


def read_stdin_lines(force=False):
    # Original consumes piped stdin even without -i.  Avoid blocking on a real tty.
    if not force and sys.stdin.isatty():
        return []
    data = sys.stdin.read()
    if data == "":
        return []
    return data.splitlines()


def format_count(value, precision):
    # Python's format uses the same round-half-even behavior observed for .0 precision.
    return (f"{value:.{precision}f}")


def run_command(command, env):
    try:
        cp = subprocess.run(["/bin/sh", "-c", command], stdin=subprocess.DEVNULL,
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                            env=env)
        code = cp.returncode
        out = cp.stdout or b""
    except Exception as e:
        code = 127
        out = (str(e) + "\n").encode()
    if out and not out.endswith(b"\n"):
        out += b"\n"
    return code, out


def main(argv):
    try:
        opts, inputs = parse_cli(argv)
        if opts["help"]:
            print_help()
            return 0
        if opts["version"]:
            sys.stdout.write(VERSION + "\n")
            return 0
        vals = validate(opts)
    except CliError as e:
        sys.stderr.write(e.msg)
        return 1

    if len(inputs) == 0:
        sys.stdout.write("No command supplied, exiting.\n")
        return 0

    command = " ".join(inputs)

    items = []
    if opts["ffor"] is not None:
        items.extend(opts["ffor"].split(","))
    stdin_items = read_stdin_lines(opts["stdin"])
    items.extend(stdin_items)

    if vals["num"] is not None:
        max_iter = vals["num"]
    elif len(items) > 0:
        max_iter = len(items)
    else:
        max_iter = None

    total_runs = 0
    successes = 0
    failures = []
    last_out = b""
    first_text = None
    expired_duration = False
    start = time.monotonic()

    i = 0
    while True:
        if max_iter is not None and i >= max_iter:
            break
        if vals["for_duration"] is not None and (time.monotonic() - start) >= vals["for_duration"]:
            expired_duration = True
            break
        if vals["until_dt"] is not None and datetime.utcnow() >= vals["until_dt"]:
            break

        if i < len(items):
            item = items[i]
        elif items:
            item = items[-1]
        else:
            item = ""

        count_value = vals["offset"] + (vals["count_by"] * i)
        env = os.environ.copy()
        env["COUNT"] = format_count(count_value, vals["count_precision"])
        env["ITEM"] = item

        code, out = run_command(command, env)
        total_runs += 1
        if code == 0:
            successes += 1
        else:
            failures.append(code)
        last_out = out
        text = out.decode(errors="replace")

        if not opts["only_last"] and out:
            try:
                sys.stdout.buffer.write(out)
                sys.stdout.buffer.flush()
            except BrokenPipeError:
                return 0

        stop = False
        if opts["until_success"] and code == 0:
            stop = True
        if opts["until_fail"] and code != 0:
            stop = True
        if opts["until_error"] is not None and str(code) == opts["until_error"]:
            stop = True
        if opts["until_contains"] is not None and opts["until_contains"] in text:
            stop = True
        if vals["until_re"] is not None and vals["until_re"].search(text):
            stop = True
        if opts["until_changes"] or opts["until_same"]:
            if first_text is None:
                first_text = text
            else:
                if opts["until_changes"] and text != first_text:
                    stop = True
                if opts["until_same"] and text == first_text:
                    stop = True
        if stop:
            break

        i += 1
        if vals["every"] > 0:
            time.sleep(vals["every"])
        else:
            # yield very briefly for zero intervals
            pass

    if opts["only_last"] and last_out:
        try:
            sys.stdout.buffer.write(last_out)
            sys.stdout.buffer.flush()
        except BrokenPipeError:
            return 0

    if opts["summary"]:
        sys.stdout.write(f"Total runs:\t{total_runs}\n")
        sys.stdout.write(f"Successes:\t{successes}\n")
        if failures:
            sys.stdout.write("Failures:\t{} ({})\n".format(len(failures), ", ".join(str(x) for x in failures)))
        else:
            sys.stdout.write("Failures:\t0\n")

    if expired_duration and opts["error_duration"]:
        return 124
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
